ROOT.scriptdef:
  SET NOCOUNT ON;DECLARE @INDSQL VARCHAR(max)
  SET @INDSQL = '
CREATE NONCLUSTERED INDEX RBVRkb ON CDN.RachunkiBankoweVat
             (
             RBV_RkbId
             )
ON '+ISNULL((SELECT QUOTENAME(fgName) FROM #XLIndexesFileGroups WHERE indName = 'RBVRkb'),QUOTENAME('PRIMARY'))
  EXEC(@INDSQL);SET NOCOUNT OFF;
;
